206	            // Tree is empty, new leaf becomes root
207	            self.root = Some(new_leaf_idx);
208	            return new_leaf_idx;
209	        };
210	
211	        // If root is a leaf, create internal node with both
212	        if matches!(self.nodes[root_idx].kind, NodeKind::Leaf { .. }) {
